import{_ as o}from"./chunks/22.DPtKHQKO.js";import{_ as r,a}from"./chunks/33.cCfpsNSZ.js";import{_ as e}from"./chunks/17.CpKVWXAe.js";import{_ as l,o as i,c as s,a0 as d}from"./chunks/framework.DRjqbEpm.js";const _=JSON.parse('{"title":"👑 Pro 版進階功能","description":"","frontmatter":{},"headers":[],"relativePath":"guide/pro-features.md","filePath":"guide/pro-features.md"}'),n={name:"guide/pro-features.md"};function c(h,t,p,g,b,u){return i(),s("div",null,[...t[0]||(t[0]=[d('<h1 id="👑-pro-版進階功能" tabindex="-1">👑 Pro 版進階功能 <a class="header-anchor" href="#👑-pro-版進階功能" aria-label="Permalink to &quot;👑 Pro 版進階功能&quot;">​</a></h1><p>V-Train 提供了一次性買斷的 <strong>Pro 版本</strong>，沒有訂閱費、沒有月費，只需付一次就能永久享用！<br> 這個頁面將完整介紹 Pro 版帶來的所有超能力，以及如何啟用。</p><hr><h2 id="🆓-免費版-vs-pro-版-對比" tabindex="-1">🆓 免費版 vs Pro 版 對比 <a class="header-anchor" href="#🆓-免費版-vs-pro-版-對比" aria-label="Permalink to &quot;🆓 免費版 vs Pro 版 對比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>免費版</th><th>Pro 版</th></tr></thead><tbody><tr><td>進度條追蹤</td><td>✅ 無限網站</td><td>✅ 無限網站</td></tr><tr><td>適應引擎訓練</td><td>✅ 完整功能</td><td>✅ 完整功能</td></tr><tr><td>規則序號分享</td><td>✅ 完整功能</td><td>✅ 完整功能</td></tr><tr><td>備份與還原</td><td>✅ 完整功能</td><td>✅ 完整功能</td></tr><tr><td>影片紀錄上限</td><td>⚠️ <strong>200 筆</strong>（含書籤額度）</td><td>✅ <strong>無限制</strong></td></tr><tr><td>浮動互動面板</td><td>✅</td><td>✅</td></tr><tr><td>書籤庫（收藏影片）</td><td>✅ 上限 100 部</td><td>✅ <strong>無限</strong></td></tr><tr><td>截圖自訂封面</td><td>✅</td><td>✅</td></tr><tr><td>隱私密碼鎖</td><td>❌</td><td>✅</td></tr></tbody></table><hr><h2 id="📊-免費版的-200-筆紀錄限制" tabindex="-1">📊 免費版的 200 筆紀錄限制 <a class="header-anchor" href="#📊-免費版的-200-筆紀錄限制" aria-label="Permalink to &quot;📊 免費版的 200 筆紀錄限制&quot;">​</a></h2><p>免費版的 V-Train 最多記錄 <strong>200 部影片</strong>的觀看進度。</p><h3 id="自動清理機制-garbage-collection" tabindex="-1">自動清理機制（Garbage Collection） <a class="header-anchor" href="#自動清理機制-garbage-collection" aria-label="Permalink to &quot;自動清理機制（Garbage Collection）&quot;">​</a></h3><p>當您看了第 <strong>201</strong> 部影片時，系統內建的「<strong>垃圾回收機制 (GC)</strong>」會自動啟動：</p><ul><li>自動找出<strong>最久沒有更新過</strong>的那一筆進度紀錄</li><li>靜悄悄地把它刪掉，騰出空間</li><li>永遠保持最新的 200 筆</li></ul><blockquote><p>😅 這就像一個只能記 200 件事的小機器人，當你教他第 201 件事時，他就必須忘記最久以前學的那件事。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">💡 書籤保護</p><p>如果您有使用 Pro 版的書籤功能，並將某部影片加入書籤庫，那麼即使是免費版的 GC 機制，也<strong>絕對不會刪除</strong>有書籤保護的影片紀錄。<br> 這是因為書籤代表「這部影片很重要」，系統會自動貼上護身符！</p></div><div class="info custom-block"><p class="custom-block-title">什麼時候會感受到 200 筆限制？</p><ul><li>您是輕度使用者（偶爾看幾部）→ 幾乎感受不到</li><li>您是<strong>重度使用者</strong>（每天看大量影片）→ 較舊的紀錄會被清除</li><li>您想要<strong>永久保存所有進度</strong> → 升級 Pro 版！</li></ul></div><hr><h2 id="🎯-pro-版三大超能力" tabindex="-1">🎯 Pro 版三大超能力 <a class="header-anchor" href="#🎯-pro-版三大超能力" aria-label="Permalink to &quot;🎯 Pro 版三大超能力&quot;">​</a></h2><h3 id="_1-無限影片紀錄容量" tabindex="-1">① 無限影片紀錄容量 <a class="header-anchor" href="#_1-無限影片紀錄容量" aria-label="Permalink to &quot;① 無限影片紀錄容量&quot;">​</a></h3><p>升級 Pro 後，200 筆的上限<strong>立刻解除</strong>，GC 機制隨即<strong>永久停工</strong>。<br> 您可以無限制地記錄所有影片的觀看進度，永不遺忘。</p><h3 id="_2-浮動互動面板-hover-panel" tabindex="-1">② 浮動互動面板（Hover Panel） <a class="header-anchor" href="#_2-浮動互動面板-hover-panel" aria-label="Permalink to &quot;② 浮動互動面板（Hover Panel）&quot;">​</a></h3><p>當您在影片<strong>播放頁面</strong>上，画面上會浮現一個精美的操作面板：</p><blockquote><p><img src="'+o+'" alt="浮動互動面板"></p></blockquote><p><strong>面板功能說明：</strong></p><table tabindex="0"><thead><tr><th>按鈕</th><th>功能</th></tr></thead><tbody><tr><td>👍 喜歡</td><td>給這部影片標記「喜歡」，縮圖上出現大拇指朝上徽章</td></tr><tr><td>👎 不喜歡</td><td>給這部影片標記「不喜歡」，縮圖上出現大拇指朝下徽章</td></tr><tr><td>❤️ 收藏</td><td>開啟資料夾選擇器，將影片加入書籤庫</td></tr><tr><td>📸 截圖</td><td>擷取當前最佳畫面作為自訂封面</td></tr><tr><td>📚 書籤庫</td><td>直接跳轉到您的個人書籤庫</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 面板位置可以拖動！</p><p>覺得面板出現的位置不順手？用滑鼠拖動面板，系統會記住您的自訂位置，下次自動出現在相同地方。</p></div><div class="info custom-block"><p class="custom-block-title">想暫時關閉浮動面板？</p><p>只需到<strong>控制面板</strong>，把「<strong>互動面板開關 (Hover Panel)</strong>」關掉，下次需要時再開啟即可。</p></div><h3 id="_3-書籤庫-bookmark-vault" tabindex="-1">③ 書籤庫（Bookmark Vault） <a class="header-anchor" href="#_3-書籤庫-bookmark-vault" aria-label="Permalink to &quot;③ 書籤庫（Bookmark Vault）&quot;">​</a></h3><p>全螢幕的個人影片管理中心！詳細說明請參閱 <a href="./bookmark-vault.html">書籤庫與互動面板</a> 頁面。</p><h3 id="_4-截圖自訂封面" tabindex="-1">④ 截圖自訂封面 <a class="header-anchor" href="#_4-截圖自訂封面" aria-label="Permalink to &quot;④ 截圖自訂封面&quot;">​</a></h3><p>在影片最精彩的畫面，點擊面板上的 📸 截圖按鈕：</p><ol><li>系統嘗試從影片的 <code>&lt;video&gt;</code> 元素或 <code>&lt;canvas&gt;</code> 擷取當前畫面</li><li>若直接擷取失敗，自動嘗試從頁面的 <code>og:image</code> 或 <code>twitter:image</code> Meta 標籤獲取圖片</li><li>圖片壓縮為 <strong>320px 寬的 WebP 格式</strong>，儲存到本地 IndexedDB</li><li>成功後，書籤庫中這部影片的封面會立刻更新為您截取的畫面</li></ol><div class="warning custom-block"><p class="custom-block-title">❌ 什麼情況下截圖會失敗？</p><ul><li>影片藏在深層的 <code>&lt;iframe&gt;</code> 中（跨網域限制）</li><li>網站有嚴格的 CORS / CSP 安全政策</li><li>截圖按鈕上出現紅色 ❌ 圖示代表截圖失敗</li></ul><p>即使截圖失敗，影片仍然可以正常收藏到書籤庫，只是使用原本的封面圖。</p></div><h3 id="_5-隱私密碼鎖-passcode-protection" tabindex="-1">⑤ 隱私密碼鎖（Passcode Protection） <a class="header-anchor" href="#_5-隱私密碼鎖-passcode-protection" aria-label="Permalink to &quot;⑤ 隱私密碼鎖（Passcode Protection）&quot;">​</a></h3><p>Pro 版允許您為 V-Train 設定一組專屬密碼：</p><ul><li>設定後，每次點擊 V-Train 圖示都需要<strong>先輸入密碼</strong></li><li>密碼保護的是「控制面板」的訪問權限，阻止他人偷看您的觀看紀錄</li><li>輸入正確密碼後，在關閉面板前不需要重複輸入</li></ul><blockquote><p><img src="'+r+'" alt="密碼鎖畫面"></p></blockquote><hr><h2 id="🔑-如何啟用-pro" tabindex="-1">🔑 如何啟用 Pro？ <a class="header-anchor" href="#🔑-如何啟用-pro" aria-label="Permalink to &quot;🔑 如何啟用 Pro？&quot;">​</a></h2><ol><li>前往 <a href="https://v-train.lemonsqueezy.com/checkout/buy/3dbcb93a-052c-433c-9adb-5fdcf221cc17" target="_blank" rel="noreferrer">V-Train Pro 購買頁面</a>（一次性買斷，無訂閱費）</li><li>完成付款後，您會收到一組<strong>授權序號（License Key）</strong></li><li>開啟 V-Train <strong>控制面板</strong>，找到底部的「<strong>⚡ 解鎖Pro(Unlock V-Train Pro)</strong>」按鈕</li><li>點擊按鈕，將授權序號貼入輸入框</li><li>系統連線驗證（需要網路）</li><li>驗證成功後，所有 Pro 功能<strong>立刻解鎖</strong>！</li></ol><blockquote><p><img src="'+a+'" alt="Pro 啟用按鈕"></p></blockquote><div class="tip custom-block"><p class="custom-block-title">💡 授權序號要保管好！</p><p>您的授權序號可以在需要時重新使用（例如換電腦）。建議把序號記錄在安全的地方，例如密碼管理器或記事本中。</p></div><hr><h2 id="🆘-忘記密碼怎麼辦" tabindex="-1">🆘 忘記密碼怎麼辦？ <a class="header-anchor" href="#🆘-忘記密碼怎麼辦" aria-label="Permalink to &quot;🆘 忘記密碼怎麼辦？&quot;">​</a></h2><p>如果您設定了密碼鎖但忘記密碼，請按照以下步驟救援：</p><blockquote><p><img src="'+e+'" alt="忘記密碼按鈕"></p></blockquote><ol><li>在密碼輸入畫面，點擊 **「忘記密碼(Forgot Passcode?)（忘記密碼）」**連結</li><li>系統會要求您輸入 <strong>Pro 授權序號</strong>作為身份驗證</li><li>輸入正確的序號後，密碼將被重置</li><li>重置後，建議立刻<strong>設定一個新密碼</strong>並<strong>備份資料</strong></li></ol><div class="danger custom-block"><p class="custom-block-title">💀 如果忘記密碼且找不到授權序號</p><p>很遺憾，在這種情況下無法重置密碼。這是為了<strong>最大化保護您的隱私</strong>所做的設計決策。<br> 唯一的解決方案是重新安裝 V-Train（<strong>將清除所有資料</strong>），然後重新購買 Pro 版。<br><strong>請務必妥善保存您的授權序號！</strong></p></div><hr><h2 id="📞-購買與支援" tabindex="-1">📞 購買與支援 <a class="header-anchor" href="#📞-購買與支援" aria-label="Permalink to &quot;📞 購買與支援&quot;">​</a></h2><ul><li>🛒 <strong>購買頁面</strong>：<a href="https://v-train.lemonsqueezy.com/checkout/buy/3dbcb93a-052c-433c-9adb-5fdcf221cc17" target="_blank" rel="noreferrer">V-Train Pro</a></li><li>💬 <strong>問題回報</strong>：<a href="https://github.com/vtrain-labs/v-train-extension/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li><li>⭐ <strong>Chrome 商店</strong>：<a href="https://chromewebstore.google.com/detail/v-train-adaptive-video-ba/cikabjkegiefjgalfncfoehmkpmkoiaf" target="_blank" rel="noreferrer">Chrome Web Store</a></li></ul><div class="info custom-block"><p class="custom-block-title">Pro 版授權說明</p><ul><li><strong>一次性買斷</strong>，無訂閱費、無月費</li><li>購買後<strong>永久有效</strong>，不受版本更新影響</li><li>授權序號在重置後可重複使用</li></ul></div>',50)])])}const v=l(n,[["render",c]]);export{_ as __pageData,v as default};
